const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stops=[{name:'Sorrento',sub:'The beginning of a good thing',day:'Day 1',note:'Our first espresso, standing at the bar. Already on Italian time.',tag:'☕ Best first coffee',x:155,y:140},{name:'Positano',sub:'Pastel houses & a slower kind of morning',day:'Day 2–3',note:'The best view wasn’t from a restaurant. It was from the steps we almost didn’t take.',tag:'✧ The unforgettable view',x:300,y:233},{name:'Fiordo di Furore',sub:'A little detour. A hidden blue.',day:'Day 4',note:'Go before 9. Just the sound of the water and a whole cove to yourself.',tag:'☀ Go early',x:420,y:265},{name:'Amalfi',sub:'Lemon everything, please',day:'Day 5',note:'Lemon sorbet in an actual lemon. We went back for a second one.',tag:'♡ Best little treat',x:515,y:215},{name:'Ravello',sub:'One last view to take home',day:'Day 6–7',note:'Stay for sunset at the gardens. Some moments don’t need a photograph.',tag:'✧ Don’t miss sunset',x:565,y:158}];let selected=1;const $=s=>document.querySelector(s);function renderStops(){$('#stop-list').innerHTML=stops.map((s,i)=>`<button class="stop ${selected===i?'selected':''}" data-stop="${i}"><span class="stop-number">${String(i+1).padStart(2,'0')}</span><span class="stop-info"><span class="stop-title">${esc(s.name)}<small>${esc(s.day)}</small></span><span class="stop-subtitle">${esc(s.sub)}</span>${selected===i?`<span class="stop-note">“${esc(s.note)}”</span><span class="stop-chip">${esc(s.tag)}</span>`:''}</span></button>`).join('');}renderStops();
const photos=['https://images.unsplash.com/photo-1632851853275-7882469dfe99?auto=format&fit=crop&w=1600&q=85','https://images.unsplash.com/photo-1530476219733-88085e45aa2c?auto=format&fit=crop&w=1000&q=85','https://images.unsplash.com/photo-1551892374-ecf8754cf8b0?auto=format&fit=crop&w=1000&q=85'];$('#hero-image').src=photos[0];$('#cove-image').src=photos[1];$('#cove-image').alt='Hillside houses and turquoise water on the Amalfi Coast';$('#food-image').src=photos[2];let notesVisible=true,zoom=1;
function mapMarkup(){return `<svg class="coast-map" viewBox="0 0 700 430" xmlns="http://www.w3.org/2000/svg" role="group" aria-label="Illustrated journey route with ${stops.length} stops"><defs><pattern id="water" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M2 17q4-2 8 0" fill="none" stroke="#c1dcd4" stroke-width=".5"/></pattern><filter id="shadow"><feDropShadow dx="0" dy="3" stdDeviation="4" flood-color="#315b41" flood-opacity=".17"/></filter><linearGradient id="land" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e7ebd9"/><stop offset="1" stop-color="#eff1e3"/></linearGradient></defs><rect width="700" height="430" fill="#d9e9e4"/><rect width="700" height="430" fill="url(#water)"/><g class="map-geography" style="transform-origin:350px 220px;transform:scale(${zoom})"><path d="M-10-10H710V360L660 340 630 307 602 290 588 261 550 250 525 249 504 263 476 281 450 294 420 285 397 282 376 271 348 259 320 256 294 251 270 243 244 228 213 232 189 215 175 192 147 186 119 194 96 186 72 194 54 182 36 184 18 170-10 173Z" fill="url(#land)" stroke="#bacfbd" stroke-width="1.5"/><g fill="none" stroke="#d1debf" stroke-width="1" opacity=".65"><path d="M20 70Q140 95 215 74T395 45 570 90 700 105M12 86Q130 105 218 93T406 65 572 109 710 125M16 100Q133 116 214 111T400 82 565 126 710 145M37 112Q135 137 228 129T414 107 565 149 710 168M59 127Q135 154 230 149T414 125 552 173 710 198M100 140Q175 169 259 162T399 145 537 192 698 223M182 182Q270 188 329 173T454 180 555 212 690 248M245 211Q282 195 337 193T452 201 527 232 661 271"/><path d="M290 0Q266 67 308 128T365 243M380 0Q330 64 363 119T401 268M515 0Q473 66 486 119T474 274M574 0Q540 50 560 116T582 249"/></g><g fill="#d3dfc1" opacity=".7"><path d="m206 15 42 18 18 35-33 16-42-20zM337 102l35-18 33 10 13 30-52 24-41-16zM470 25l42 6 22 37-33 15-41-28zM575 144l36-25 29 38-28 24zM112 82l41-15 30 33-29 19z"/></g><g fill="none" stroke-linecap="round"><path d="M49 156Q128 118 168 141T298 234 421 265 515 215 565 158 684 189" stroke="#fff" stroke-width="7"/><path d="M49 156Q128 118 168 141T298 234 421 265 515 215 565 158 684 189" stroke="#d5d9bb" stroke-width="1.3"/><path d="M155 140Q213 121 266 117T437 101 568 157M299 231Q327 174 369 126T440 43M421 265Q421 211 447 165T518 75" stroke="#fff" stroke-width="3"/><path d="${stops.map((s,i)=>(i?'L':'M')+s.x+' '+s.y).join(' ')}" stroke="#fff" stroke-width="7"/><path d="${stops.map((s,i)=>(i?'L':'M')+s.x+' '+s.y).join(' ')}" stroke="#729675" stroke-width="2.2" stroke-dasharray="5 5"/></g><g font-family="'DM Sans',sans-serif" fill="#9caa8e" font-size="10"><text x="230" y="85" letter-spacing="2">MONTI LATTARI</text><text x="213" y="325" fill="#8daea0" font-family="Georgia" font-style="italic" font-size="18" letter-spacing="2">Tyrrhenian Sea</text><text x="54" y="145" font-size="9">Massa Lubrense</text><text x="357" y="214" font-size="9">Praiano</text><text x="580" y="79" font-size="9">Scala</text><text x="625" y="235" font-size="9">Maiori</text></g>${stops.map((s,i)=>`<g class="map-pin ${i===selected?'is-selected':''}" data-pin="${i}" tabindex="0" role="button" aria-label="${esc(s.name)}: ${esc(s.note)}" transform="translate(${s.x},${s.y})"><circle r="${i===selected?22:15}" fill="#ffffff48" stroke="#ffffffbb"/><circle r="${i===selected?15:10}" fill="${i===selected?'#416e4b':'#fff'}" stroke="${i===selected?'#fff':'#769977'}" stroke-width="2" filter="url(#shadow)"/><text text-anchor="middle" dy="4" font-family="DM Sans,sans-serif" font-size="${i===selected?11:9}" font-weight="600" fill="${i===selected?'#fff':'#68886b'}">${i+1}</text><text text-anchor="middle" y="${i===selected?36:-23}" font-family="DM Sans,sans-serif" font-size="${i===selected?12:10}" font-weight="${i===selected?650:500}" fill="#5d7557">${esc(s.name)}</text></g>`).join('')}</g></svg>${notesVisible?`<div class="pin-note glass"><span class="note-eyebrow">${esc(stops[selected].day)} &nbsp; · &nbsp; A LITTLE MEMORY</span><div class="pin-note-title">${esc(stops[selected].name)}<span>♡</span></div><p>“${esc(stops[selected].note)}”</p><span class="note-category">${esc(stops[selected].tag)}</span></div>`:''}`;}function renderMap(){$('#map-canvas').innerHTML=mapMarkup();}renderMap();

let saved=false,toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3400)}
function selectStop(index){if(!Number.isInteger(index)||index<0||index>=stops.length)throw new Error('Choose an existing stop.');selected=index;renderStops();renderMap();}
document.addEventListener('click',e=>{const stop=e.target.closest('[data-stop]');const pin=e.target.closest('[data-pin]');if(stop)selectStop(Number(stop.dataset.stop));if(pin)selectStop(Number(pin.dataset.pin));});document.addEventListener('keydown',e=>{const pin=e.target.closest('[data-pin]');if(pin&&['Enter',' '].includes(e.key)){e.preventDefault();selectStop(Number(pin.dataset.pin));}});
$('#toggle-notes').onclick=()=>{notesVisible=!notesVisible;$('#toggle-notes').textContent=notesVisible?'☷  Notes on':'☷  Notes off';$('#toggle-notes').setAttribute('aria-pressed',notesVisible);renderMap()};document.querySelectorAll('[data-mapstyle]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-mapstyle]').forEach(x=>x.classList.toggle('active',x===b));$('#map-shell').classList.toggle('terrain',b.dataset.mapstyle==='terrain')});$('#zoom-in').onclick=()=>{zoom=Math.min(1.7,zoom+.15);renderMap()};$('#zoom-out').onclick=()=>{zoom=Math.max(.8,zoom-.15);renderMap()};$('#reset-map').onclick=()=>{zoom=1;renderMap()};$('#save-journey').onclick=()=>{saved=!saved;savedJourney=saved?structuredClone(currentJourney):null;$('#save-journey').style.background=saved?'#d6e6d4':'';$('#save-journey').setAttribute('aria-label',saved?'Unsave journey':'Save journey');$('#save-journey').setAttribute('aria-pressed',saved);toast(saved?'Journey added to your saved places':'Journey removed from saved places')};
let currentPhotos=[...photos],currentTitle='A little closer to la dolce vita.',createdJourneys=[],step=1,draft=null,photoChoices=[...photos];const initialStops=structuredClone(stops);let currentJourney={id:'original',title:currentTitle,selected:[...photos],location:'Amalfi Coast, Italy',start:'2026-06-12',end:'2026-06-18',caption:'Salt in our hair. Absolutely no plans. A week of winding roads, long lunches, and places we didn’t want to leave.',stops:structuredClone(stops)},savedJourney=null;const dialog=$('#composer');
function openModal(title,body){dialog.setAttribute('aria-label',title);$('#composer-content').innerHTML=`<div class="modal-header"><span class="eyebrow">ATLAS · YOUR WORLD, REMEMBERED</span><button class="close-button" data-close aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function openComposer(){step=1;if(!draft)draft={selected:[],title:'',location:'Amalfi Coast, Italy',start:'2026-06-12',end:'2026-06-18',caption:'',stops:initialStops.map(s=>({...s}))};renderComposer();}
function stepper(){return `<div class="stepper">${['Choose photos','Tell your story','Make it yours'].map((t,i)=>`<span class="${step===i+1?'current':step>i+1?'complete':''}"><b>${step>i+1?'✓':i+1}</b>${t}</span>`).join('')}</div>`}
function renderComposer(){let body='';if(step===1){body=`<h2>Every journey starts<br>with <em>a moment.</em></h2><p class="modal-description">Choose the photos that bring you right back.</p><label class="upload-area" id="drop-zone"><span class="upload-icon">＋</span><strong>Add your photos</strong><span>Choose files or drop them here · JPG, PNG, WebP</span><input id="photo-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><div class="picker-heading"><span>Or try these travel memories</span><span>${draft.selected.length} selected</span></div><div class="photo-picker">${photoChoices.map((src,i)=>`<button class="pick-photo ${draft.selected.includes(src)?'picked':''}" data-photo="${i}" aria-label="${draft.selected.includes(src)?'Deselect':'Select'} photo ${i+1}" aria-pressed="${draft.selected.includes(src)}"><img src="${esc(src)}" alt="Travel memory ${i+1}"><span class="pick-check">${draft.selected.includes(src)?draft.selected.indexOf(src)+1:'＋'}</span>${draft.selected[0]===src?'<span class="cover-label">Cover photo</span>':''}</button>`).join('')}</div><div class="composer-hint">The first photo you select becomes your cover.</div>`}
if(step===2){body=`<h2>The places.<br><em>And the feeling.</em></h2><p class="modal-description">A few words today. A world of memories later.</p><div class="field"><label for="journey-title">Give your journey a name</label><input id="journey-title" maxlength="90" placeholder="A little closer to la dolce vita" value="${esc(draft.title)}"></div><div class="field"><label for="journey-location">Where did you go?</label><input id="journey-location" maxlength="90" value="${esc(draft.location)}"></div><div class="date-fields"><div class="field"><label for="start-date">From</label><input id="start-date" type="date" value="${draft.start}"></div><div class="field"><label for="end-date">Until</label><input id="end-date" type="date" value="${draft.end}"></div></div><div class="field"><label for="journey-caption">Your story <span>optional</span></label><textarea id="journey-caption" rows="2" maxlength="1000" placeholder="The things you never want to forget…">${esc(draft.caption)}</textarea></div><div class="editor-label"><strong>The stops along the way</strong><span>Tap a stop to leave a note</span></div><div class="stop-editors">${draft.stops.map((s,i)=>`<details class="stop-editor" ${i===0?'open':''}><summary><span class="stop-number">${i+1}</span>${esc(s.name)}<span class="expand-symbol">＋</span></summary><div class="stop-editor-content"><div class="field"><label for="place-${i}">Place name</label><input id="place-${i}" data-place="${i}" value="${esc(s.name)}" maxlength="65"></div><div class="field"><label for="anchor-${i}">On the map, near</label><select id="anchor-${i}" data-anchor="${i}"><option value="">Keep current location</option>${initialStops.map((a,n)=>`<option value="${n}">${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="note-${i}">What stayed with you?</label><textarea id="note-${i}" data-note="${i}" maxlength="400" rows="2">${esc(s.note)}</textarea></div><div class="field"><label for="tag-${i}">The highlight</label><select id="tag-${i}" data-tag="${i}">${[s.tag,'♡ Favorite place','☕ Best coffee','✧ Best view','☀ Go early','◌ Hidden gem','↗ Worth the detour'].filter((v,n,a)=>a.indexOf(v)===n).map(t=>`<option>${esc(t)}</option>`).join('')}</select></div><div class="stop-edit-actions"><button class="remove-stop" data-remove-stop="${i}">Remove stop</button><button class="move-stop" data-move-stop="${i}" ${i===0?'disabled':''}>↑ Move earlier</button></div></div></details>`).join('')}</div><button class="add-stop" id="add-stop">＋ Add a stop</button>`;}
if(step===3){body=`<h2>A story worth <em>keeping.</em></h2><p class="modal-description">One last look before it becomes a memory.</p><div class="review-cover"><img src="${esc(draft.selected[0])}" alt="Your journey cover"><div class="review-overlay"><span>${esc(draft.location)}</span><h3>${esc(draft.title)}</h3><span>${draft.selected.length} photos &nbsp; · &nbsp; ${draft.stops.length} stops</span></div></div><div class="review-route">${draft.stops.map((s,i)=>`<span><b>${i+1}</b>${esc(s.name)}</span>`).join('<i>·</i>')}</div><div class="review-note">${esc(draft.caption||'A new chapter in your travel journal.')}</div><div class="post-settings"><div><strong>Show my notes on the map</strong><span>Give every stop a little more meaning.</span></div><label class="switch"><input type="checkbox" aria-label="Show my notes on the map" id="review-notes" ${notesVisible?'checked':''}><span></span></label></div><div class="preview-disclosure">◌ Interactive design preview · your post stays in this session.</div>`;}
openModal('Create a journey',`${stepper()}<div class="composer-step">${body}</div><div class="composer-footer"><button class="back-button" id="composer-back">${step===1?'Save for later':'← Back'}</button><span class="step-count">${step} of 3</span><button class="primary" id="composer-next" ${step===1&&!draft.selected.length?'disabled':''}>${step===3?'Post journey ↗':'Continue →'}</button></div>`);
$('#composer-next').onclick=()=>{if(step===1){if(!draft.selected.length)return;step=2;renderComposer()}else if(step===2){collectDraft();if(!draft.title.trim()){toast('Give your journey a name first');$('#journey-title').focus();return}if(!draft.location.trim()){toast('Add a destination for this journey');$('#journey-location').focus();return}if(!draft.start||!draft.end||draft.end<draft.start){toast('Choose an end date after your start date');return}if(!draft.stops.length){toast('Add at least one stop to your journey');return}step=3;renderComposer()}else{notesVisible=$('#review-notes').checked;postJourney()}};$('#composer-back').onclick=()=>{if(step===1){dialog.close();toast('Your draft is here when you’re ready')}else{if(step===2)collectDraft();step--;renderComposer()}};
if(step===1){$('#photo-upload').onchange=e=>loadFiles(e.target.files);const drop=$('#drop-zone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging')};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();loadFiles(e.dataTransfer.files)}}if(step===2){$('#add-stop').onclick=()=>{collectDraft();if(draft.stops.length>=12){toast('Keep this journey to 12 meaningful stops.');return}const anchor=initialStops[1];draft.stops.push({name:'A little discovery',sub:'A moment worth keeping',day:'Day '+(draft.stops.length+1),note:'',tag:'◌ Hidden gem',x:anchor.x+14,y:anchor.y-15});renderComposer();document.querySelector('.stop-editor:last-child').open=true;document.querySelector('.stop-editor:last-child').scrollIntoView({block:'nearest',behavior:'smooth'})}}}
function collectDraft(){if(!$('#journey-title'))return;draft.title=$('#journey-title').value.trim();draft.location=$('#journey-location').value.trim();draft.start=$('#start-date').value;draft.end=$('#end-date').value;draft.caption=$('#journey-caption').value.trim();document.querySelectorAll('[data-place]').forEach(el=>draft.stops[Number(el.dataset.place)].name=el.value.trim()||'A little discovery');document.querySelectorAll('[data-anchor]').forEach(el=>{if(el.value!==''){const a=initialStops[Number(el.value)];draft.stops[Number(el.dataset.anchor)].x=a.x;draft.stops[Number(el.dataset.anchor)].y=a.y}});document.querySelectorAll('[data-note]').forEach(el=>draft.stops[Number(el.dataset.note)].note=el.value.trim());document.querySelectorAll('[data-tag]').forEach(el=>draft.stops[Number(el.dataset.tag)].tag=el.value);}
async function loadFiles(files){const valid=[...files].filter(f=>['image/jpeg','image/png','image/webp'].includes(f.type)&&f.size<=15*1024*1024);if(valid.length!==files.length)toast('Use JPG, PNG or WebP photos under 15 MB.');for(const file of valid.slice(0,20)){const src=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>resolve(null);r.readAsDataURL(file)});if(src){photoChoices.push(src);draft.selected.push(src)}}renderComposer();}
function postJourney(){const created={...structuredClone(draft),id:Date.now()};createdJourneys.unshift(created);applyJourney(created);draft=null;dialog.close();toast('Your journey is posted. A little piece of your world, kept.');window.scrollTo({top:0,behavior:'smooth'});}
function applyJourney(journey){currentJourney={...structuredClone(journey),id:journey.id||'original'};saved=!!savedJourney&&savedJourney.id===currentJourney.id;$('#save-journey').style.background=saved?'#d6e6d4':'';$('#save-journey').setAttribute('aria-label',saved?'Unsave journey':'Save journey');$('#save-journey').setAttribute('aria-pressed',saved);$('.photo-grid').classList.remove('photos-1','photos-2');if(journey.selected.length<3)$('.photo-grid').classList.add('photos-'+journey.selected.length);currentTitle=journey.title;currentPhotos=[...journey.selected];$('.heading h1').textContent=journey.title;$('.eyebrow').innerHTML='<span class="tiny-line"></span> A NEW CHAPTER';$('.trip-meta').innerHTML=`<span>⌖ ${esc(journey.location)}</span><i></i><span>${new Date(journey.start+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric'})} – ${new Date(journey.end+'T12:00:00').toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'})}</span><i></i><span>${journey.selected.length} moments worth keeping</span>`;$('.intro-note').textContent=journey.caption||'A new chapter in my travel journal.';['#hero-image','#cove-image','#food-image'].forEach((id,i)=>{$(id).src=currentPhotos[i%currentPhotos.length];$(id).alt='Photo '+(i+1)+' from '+journey.title});$('.photo-label').textContent='⌖ '+journey.location;$('.small-photo-label').textContent='Along the way';$('.photo-third .small-photo-label').textContent='A little memory';stops.splice(0,stops.length,...journey.stops);selected=0;$('.count-pill').textContent=stops.length+' stops';$('.map-top .map-tag').innerHTML=`<span class="green-dot"></span>${stops.length} places. One good story.`;$('#toggle-notes').textContent=notesVisible?'☷  Notes on':'☷  Notes off';renderStops();renderMap();}
function showGallery(){const g=$('#gallery');g.setAttribute('aria-label','Journey photos');$('#gallery-content').innerHTML=`<div class="gallery-heading"><span class="eyebrow">THE CAMERA ROLL</span><h2>${esc(currentTitle)}</h2><span>${currentPhotos.length} moments, kept.</span></div><div class="gallery-photos">${currentPhotos.map((src,i)=>`<figure><img src="${esc(src)}" alt="Journey photograph ${i+1}"><figcaption>Moment ${String(i+1).padStart(2,'0')}</figcaption></figure>`).join('')}</div>`;g.showModal()};$('#all-photos').onclick=showGallery;$('#close-gallery').onclick=()=>$('#gallery').close();
function showCollection(view){const title=view==='saved'?'Places to come back to.':view==='discover'?'A little inspiration.':'Your world, in chapters.';const sub=view==='saved'?'The journeys you want to keep close.':view==='discover'?'Small discoveries from the Italian coast.':'Every journey has a story. These are yours.';let cards='';if(view!=='saved'||saved){cards=`<button class="collection-card" data-open-original><img src="${photos[0]}" alt="Positano"><div><span class="eyebrow">ITALY · 7 DAYS</span><h3>A little closer to la dolce vita.</h3><span>5 stops · 3 photos</span></div><span class="card-arrow">↗</span></button>`;}if(view==='saved'&&savedJourney){const j=savedJourney;cards=`<button class="collection-card" data-open-saved><img src="${esc(j.selected[0])}" alt="${esc(j.title)}"><div><span class="eyebrow">${esc(j.location)}</span><h3>${esc(j.title)}</h3><span>${j.stops.length} stops · ${j.selected.length} photos</span></div><span class="card-arrow">↗</span></button>`;}if(view==='journeys')cards=createdJourneys.map((j,i)=>`<button class="collection-card" data-open-created="${i}"><img src="${esc(j.selected[0])}" alt="${esc(j.title)}"><div><span class="eyebrow">${esc(j.location)}</span><h3>${esc(j.title)}</h3><span>${j.stops.length} stops · ${j.selected.length} photos</span></div><span class="card-arrow">↗</span></button>`).join('')+cards;openModal(title,`<h2 class="collection-title">${title}</h2><p class="modal-description">${sub}</p>${cards||'<div class="empty-saved"><span>♡</span><h3>A place for your favorite places.</h3><p>Tap the bookmark on a journey to keep it here.</p></div>'}${view==='journeys'?'<button class="primary" data-start>＋ New journey</button>':''}`);}
$('#new-journey').onclick=openComposer;$('#all-journeys').onclick=()=>showCollection('journeys');document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showCollection(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();showCollection('journeys')};$('.nav-right .avatar').onclick=()=>openModal('Your profile',`<div class="profile-preview"><span class="avatar">R</span><h2>Rohit’s little world.</h2><p>Collecting moments, one place at a time.</p><div class="profile-stats"><span><strong>${createdJourneys.length+1}</strong>journeys</span><span><strong>${createdJourneys.reduce((n,j)=>n+j.stops.length,5)}</strong>memories</span><span><strong>1</strong>country</span></div><button class="primary" data-start>Keep a new memory</button></div>`);
$('#share-journey').onclick=()=>openModal('Share journey',`<h2>A good story is<br><em>better shared.</em></h2><p class="modal-description">Share the original coastal journey preview with someone who’d love it.</p><div class="share-preview"><img src="${photos[0]}" alt="Amalfi Coast"><span>A little closer to la dolce vita.<small>Amalfi Coast, Italy · 5 stops</small></span></div><button class="primary full" id="copy-link">Copy preview link ↗</button><p class="preview-disclosure">Access follows this site’s privacy settings. New posts are visible only in your current session.</p>`);
document.addEventListener('click',async e=>{if(e.target.closest('[data-close]')){if(step===2&&draft)collectDraft();dialog.close()}if(e.target.closest('[data-start]'))openComposer();const pick=e.target.closest('[data-photo]');if(pick){const src=photoChoices[Number(pick.dataset.photo)];if(draft.selected.includes(src))draft.selected=draft.selected.filter(v=>v!==src);else draft.selected.push(src);renderComposer()}const remove=e.target.closest('[data-remove-stop]');if(remove){collectDraft();draft.stops.splice(Number(remove.dataset.removeStop),1);renderComposer()}const move=e.target.closest('[data-move-stop]');if(move){collectDraft();const i=Number(move.dataset.moveStop);if(i>0){[draft.stops[i-1],draft.stops[i]]=[draft.stops[i],draft.stops[i-1]];renderComposer()}}if(e.target.closest('[data-open-saved]')&&savedJourney){applyJourney(savedJourney);dialog.close()}const created=e.target.closest('[data-open-created]');if(created){applyJourney(createdJourneys[Number(created.dataset.openCreated)]);dialog.close()}if(e.target.closest('[data-open-original]')){applyJourney({title:'A little closer to la dolce vita.',selected:photos,location:'Amalfi Coast, Italy',start:'2026-06-12',end:'2026-06-18',caption:'Salt in our hair. Absolutely no plans. A week of winding roads, long lunches, and places we didn’t want to leave.',stops:structuredClone(initialStops)});dialog.close()}if(e.target.closest('#copy-link')){try{await navigator.clipboard.writeText(location.origin+location.pathname);toast('Preview link copied');dialog.close()}catch{const p=document.createElement('p');p.className='copy-fallback';p.textContent=location.origin+location.pathname;$('#composer-content .modal-body').append(p);toast('Select and copy the link below')}}});
for(const d of [dialog,$('#gallery')]){d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d===dialog&&step===2&&draft)collectDraft();d.close()}}})}dialog.addEventListener('cancel',()=>{if(step===2&&draft)collectDraft()});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'select_journey_stop',title:'Explore a journey stop',description:'Select a stop to display its location and memory on the journey map.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){selectStop(input.index);return {selectedStop:stops[selected].name,note:stops[selected].note}}});register({name:'start_journey_creation',title:'Start a new journey',description:'Open the photo selection step. This does not post a journey.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){openComposer();return {step:'Choose photos',posted:false}}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
